INSERT INTO evaluation_jury (id,candidat_id,numero_jury,nom_jury,poste_jury,note_presentation,note_motivation,note_competences,note_communication,note_culture,commentaire,score_jury,date_evaluation) VALUES (5,20,4,'Fati RBIKI','',10.0,10.0,18.5,10.0,10.0,'',11.7,'2026-08-27 13:58:50.970755') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions_entretien (id,candidat_id,questions_json,posees_json,coche_par_json,updated_at) VALUES (1,1,'["Vous êtes titulaire d''un Master en Gestion des entreprises et non d''un diplôme d''architecture : comment compensez-vous cette lacune technique pour piloter des projets architecturaux complexes ?", "Décrivez concrètement votre méthodologie pour coordonner les phases d''un projet architectural, de l''esquisse jusqu''à la réception des travaux.", "Comment gérez-vous les écarts entre le budget initial et les coûts réels d''un projet de construction, notamment dans un contexte de marché public soumis au Code des Marchés Marocains ?", "Sur vos 9 années d''expérience, citez un projet dont vous avez assuré le pilotage complet et précisez votre rôle exact, le budget engagé et les délais respectés ou non.", "Votre formation est orientée gestion d''entreprise : en quoi cela constitue-t-il, selon vous, un atout réel pour un poste de chef de projets architecte dans une agence publique ?", "Avez-vous déjà travaillé sur des projets à maîtrise d''ouvrage publique ? Si oui, quelles contraintes spécifiques avez-vous rencontrées par rapport au secteur privé ?", "Qu''est-ce qui vous motive à rejoindre l''ADER Fès-Meknès plutôt qu''un bureau d''études privé ou un promoteur immobilier ?", "Où vous situez-vous professionnellement dans 5 ans, et en quoi ce poste s''inscrit-il dans cette trajectoire ?", "Que savez-vous des missions et des projets structurants portés par l''ADER Fès-Meknès dans le cadre du développement régional ?", "Le secteur public impose des contraintes réglementaires, des délais administratifs longs et une redevabilité publique : comment vous y adaptez-vous concrètement ?"]','[]','{}','2026-08-27 13:24:57.773679') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions_entretien (id,candidat_id,questions_json,posees_json,coche_par_json,updated_at) VALUES (2,2,'["En tant qu''architecte de solutions, quels patterns architecturaux (microservices, SOA, event-driven) avez-vous déployés concrètement, et dans quel contexte avez-vous choisi l''un plutôt qu''un autre ?", "Comment garantissez-vous la sécurité, la scalabilité et l''interopérabilité d''un système d''information dans un environnement multi-entités comme une agence publique régionale ?", "Votre formation est en informatique, non en architecture du bâtiment — comment compensez-vous cette différence par rapport au titre du poste, et quelle valeur ajoutée apportez-vous concrètement à un projet de type « Chef de Projets Architecte » ?", "Sur vos 8 années d''expérience, citez un projet complexe que vous avez piloté de A à Z : quelles étaient les contraintes, les risques rencontrés et comment les avez-vous gérés ?", "Avez-vous déjà travaillé avec des équipes pluridisciplinaires ou des prestataires externes ? Comment organisez-vous la coordination et le suivi des livrables ?", "Votre score de correspondance au poste est de 67,4% — selon vous, quels sont les écarts entre votre profil actuel et les exigences du poste, et comment comptez-vous les combler ?", "Pourquoi postulez-vous à un poste de chef de projets dans le secteur public alors que le secteur privé offre généralement des rémunérations plus compétitives pour votre profil ?", "Dans cinq ans, où vous voyez-vous professionnellement, et en quoi ce poste à l''ADER s''inscrit-il dans cette trajectoire ?", "Que savez-vous du rôle et des missions de l''Agence de Développement Régional de Fès-Meknès, et quels sont selon vous les défis numériques ou infrastructurels prioritaires pour la région ?", "La gestion de projets en milieu public implique des contraintes spécifiques : marchés publics, délais administratifs, reddition de comptes — avez-vous déjà été confronté à ce cadre, et comment vous y adaptez-vous ?"]','[]','{}','2026-08-27 13:25:45.016067') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions_entretien (id,candidat_id,questions_json,posees_json,coche_par_json,updated_at) VALUES (3,3,'["Pouvez-vous décrire concrètement un projet architectural ou d''aménagement que vous avez piloté de A à Z, en précisant votre rôle exact et les livrables produits ?", "Votre diplôme est en informatique, alors que le poste exige des compétences en architecture et gestion de projets : quelles formations complémentaires, certifications ou expériences terrain vous ont permis de combler cet écart ?", "Quels outils utilisez-vous pour la conception, le suivi et la coordination de projets architecturaux (BIM, AutoCAD, MS Project, etc.) et à quel niveau de maîtrise ?", "Comment gérez-vous la coordination entre les différents corps de métiers (architectes, ingénieurs, entreprises de travaux) sur un projet de grande envergure ?", "Sur vos 8 années d''expérience, dans quels secteurs d''activité avez-vous principalement exercé, et combien de ces années sont directement liées à des projets architecturaux ou urbains ?", "Avez-vous déjà travaillé dans un environnement régi par le Code des marchés publics marocain ou des procédures administratives similaires ? Si oui, dans quel cadre ?", "Qu''est-ce qui vous motive à rejoindre une agence de développement régional plutôt qu''un bureau d''études ou une entreprise privée dans votre domaine ?", "Où vous voyez-vous dans 5 ans, et en quoi ce poste à l''ADER s''inscrit-il dans votre trajectoire professionnelle ?", "Que savez-vous des missions et des projets structurants portés par l''ADER Fès-Meknès, et lequel vous interpelle le plus professionnellement ?", "Le secteur public impose des contraintes de délais, de budget et de redevabilité spécifiques : comment percevez-vous ces contraintes et comment y avez-vous fait face dans vos expériences passées ?"]','[]','{}','2026-08-27 13:25:57.361653') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions_entretien (id,candidat_id,questions_json,posees_json,coche_par_json,updated_at) VALUES (4,4,'["Quelles sont les étapes clés d''un projet architectural, de la phase de conception jusqu''à la réception des travaux, et quel rôle joue le chef de projet à chacune d''elles ?", "Quels outils ou logiciels de conception architecturale ou de gestion de projet connaissez-vous, et à quel niveau maîtrisez-vous chacun d''eux concrètement ?", "Comment assureriez-vous le suivi technique et administratif d''un chantier tout en respectant les délais, le budget et les normes réglementaires en vigueur au Maroc ?", "Votre diplôme est une Licence générale obtenue à NEXA Digital School en 2024 — quelle est la relation entre cette formation et le métier d''architecte chef de projet pour lequel vous postulez ?", "Sans expérience professionnelle, sur quels projets concrets — académiques, personnels ou bénévoles — pouvez-vous vous appuyer pour démontrer une capacité à piloter un projet de bout en bout ?", "Avez-vous déjà collaboré avec des équipes pluridisciplinaires (ingénieurs, techniciens, maîtres d''ouvrage) dans un contexte de projet, même à titre scolaire ou associatif ?", "Pourquoi postulez-vous à un poste de Chef de projets Architecte alors que votre formation et votre profil semblent orientés vers le numérique — quelle est la logique de ce choix de carrière ?", "Où vous voyez-vous professionnellement dans cinq ans, et en quoi ce poste à l''ADER s''inscrit-il dans cette trajectoire ?", "Que savez-vous du rôle et des missions de l''Agence de Développement Régional de Fès-Meknès, et quels types de projets l''ADER pilote-t-elle sur le territoire ?", "Quelles sont, selon vous, les principales contraintes spécifiques à la gestion de projets d''architecture dans le secteur public marocain par rapport au secteur privé ?"]','[]','{}','2026-08-27 13:26:10.337150') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions_entretien (id,candidat_id,questions_json,posees_json,coche_par_json,updated_at) VALUES (5,5,'["Quels outils ou méthodes utilisez-vous pour élaborer et suivre un budget prévisionnel dans un contexte organisationnel complexe ?", "Comment procédez-vous pour analyser les écarts entre les réalisations financières et les objectifs fixés, et quelles actions correctives proposez-vous habituellement ?", "Quelle est votre approche pour mettre en place un tableau de bord de gestion permettant de piloter la performance d''une structure comme une agence de développement régional ?", "Pouvez-vous nous décrire le contexte de votre expérience de 4 ans et les missions de gestion ou de contrôle qui vous ont le plus préparé à ce poste ?", "Avez-vous déjà géré des projets ou des dossiers en lien avec des financements publics ou des partenariats institutionnels ? Si oui, décrivez un exemple concret.", "Quelle a été la situation professionnelle la plus complexe que vous avez gérée, et comment l''avez-vous résolue ?", "Pourquoi souhaitez-vous rejoindre l''ADER Fès-Meknès à ce stade de votre parcours, et qu''espérez-vous apporter à cette structure ?", "Où vous voyez-vous professionnellement dans 5 ans, et en quoi ce poste de CGM s''inscrit-il dans votre projet de carrière ?", "Que savez-vous des missions principales de l''ADER Fès-Meknès et de son rôle dans le développement économique de la région ?", "Quelles sont, selon vous, les spécificités du contrôle de gestion dans le secteur public par rapport au secteur privé, et comment y adaptez-vous vos pratiques ?"]','[]','{}','2026-08-27 13:26:21.963149') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions_entretien (id,candidat_id,questions_json,posees_json,coche_par_json,updated_at) VALUES (6,6,'["Comment construisez-vous un tableau de bord de gestion permettant de piloter efficacement les indicateurs financiers et opérationnels d''une structure publique ?", "Quelles méthodes utilisez-vous pour analyser les écarts entre le budget prévisionnel et l''exécution budgétaire, et quelles actions correctives proposez-vous généralement ?", "Comment abordez-vous la mise en place d''un contrôle interne dans un environnement où les procédures sont encore peu formalisées ?", "Pouvez-vous décrire une mission concrète de contrôle de gestion que vous avez menée durant vos 6 années d''expérience, en précisant votre méthodologie et les résultats obtenus ?", "Avez-vous déjà travaillé sur des projets impliquant plusieurs directions ou parties prenantes ? Comment avez-vous géré les tensions éventuelles autour des données chiffrées ?", "En quoi votre formation à l''ENCG vous a-t-elle préparé aux spécificités du contrôle de gestion dans le secteur public ou para-public ?", "Qu''est-ce qui vous motive à rejoindre l''ADER plutôt qu''une structure privée, alors que votre profil aurait clairement de la valeur dans les deux univers ?", "Où vous voyez-vous dans 5 ans au sein d''une agence de développement régional, et quel rôle souhaitez-vous jouer dans l''évolution de la structure ?", "Que savez-vous des missions de l''ADER Fès-Meknès et de son rôle dans le cadre de la régionalisation avancée au Maroc ?", "Quelles sont, selon vous, les principales contraintes budgétaires et réglementaires auxquelles font face les établissements publics marocains, et comment le contrôle de gestion peut-il y apporter une réponse ?"]','[]','{}','2026-08-27 13:26:33.183410') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions_entretien (id,candidat_id,questions_json,posees_json,coche_par_json,updated_at) VALUES (7,7,'["Comment construisez-vous un tableau de bord de gestion pour suivre la performance financière d''une structure publique comme l''ADER, et quels indicateurs clés y intégreriez-vous en priorité ?", "Face à un écart significatif entre le budget prévisionnel et l''exécution réelle en cours d''exercice, quelle démarche analytique et corrective mettez-vous en place ?", "Quelles sont, selon vous, les spécificités du contrôle de gestion dans un établissement public par rapport au secteur privé, notamment en matière de comptabilité analytique et de mesure de la performance ?", "Au cours de vos 5 années d''expérience, pouvez-vous citer une mission de contrôle de gestion dont vous êtes particulièrement fier et expliquer votre valeur ajoutée concrète ?", "Avez-vous déjà piloté ou participé à l''élaboration d''un business plan ou d''un budget annuel ? Décrivez votre rôle et la méthodologie utilisée ?", "Comment avez-vous géré une situation où vos analyses financières ont suscité des résistances de la part d''équipes opérationnelles ou de la direction ?", "Pourquoi souhaitez-vous rejoindre l''ADER Fès-Meknès aujourd''hui, et qu''est-ce qui vous attire spécifiquement dans le passage vers un établissement public de développement régional ?", "Dans 3 à 5 ans, comment envisagez-vous l''évolution de votre rôle de Contrôleur de Gestion au sein d''une structure comme l''ADER ?", "Que savez-vous des missions et des axes stratégiques de l''ADER Fès-Meknès, et comment le contrôle de gestion peut-il, selon vous, contribuer directement à l''atteinte de ses objectifs de développement régional ?", "La régionalisation avancée au Maroc confère aux agences régionales un rôle croissant dans l''investissement et l''attractivité territoriale — quels défis financiers et de gouvernance cela implique-t-il pour un contrôleur de gestion ?"]','[]','{}','2026-08-27 13:26:46.335053') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions_entretien (id,candidat_id,questions_json,posees_json,coche_par_json,updated_at) VALUES (8,8,'["Pouvez-vous décrire concrètement les outils de conception architecturale que vous maîtrisez (AutoCAD, Revit, ArchiCAD...) et donner un exemple de projet où vous les avez utilisés ?", "Comment procédez-vous pour vérifier la conformité d''un projet architectural aux normes de construction en vigueur au Maroc, notamment le RPS 2000 ou le CPTED ?", "Dans le cadre d''un projet de bâtiment public, quelles sont selon vous les étapes clés d''un dossier d''appel d''offres sur le plan architectural, de l''esquisse au DCE ?", "Votre score de correspondance avec ce poste est de 34 % : quelles compétences spécifiques à ce poste estimez-vous devoir encore développer, et comment comptez-vous y remédier ?", "En 6 ans d''expérience, quel est le projet dont vous êtes le plus fier et quel a été précisément votre rôle dans sa réalisation ?", "Avez-vous déjà travaillé sur des projets d''aménagement territorial ou urbain, et si oui, en collaboration avec quels types d''acteurs institutionnels ?", "Pourquoi postulez-vous à un poste d''Assistant Architecte alors que vous avez 6 ans d''expérience et un Master d''une grande école d''ingénieurs ?", "Où vous voyez-vous professionnellement dans 5 ans, et en quoi l''ADER s''inscrit-elle dans cette trajectoire ?", "Que savez-vous des missions et des projets structurants portés par l''ADER Fès-Meknès dans la région ?", "Quelle est votre perception du rôle d''un architecte au sein d''un établissement public par rapport au secteur privé ?"]','[]','{}','2026-08-27 13:27:00.555286') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions_entretien (id,candidat_id,questions_json,posees_json,coche_par_json,updated_at) VALUES (9,9,'["Quels logiciels de dessin technique maîtrisez-vous (AutoCAD, Revit, SketchUp…) et à quel niveau d''utilisation vous situez-vous concrètement ?", "Comment procédez-vous pour réaliser un plan d''exécution à partir d''un avant-projet sommaire fourni par un architecte ?", "Citez les principales normes de construction applicables au Maroc que vous avez été amené à consulter ou à appliquer dans votre travail.", "Décrivez une mission concrète que vous avez réalisée durant votre année d''expérience et quel a été votre rôle exact dans cette mission.", "Avez-vous déjà travaillé sur un projet de bâtiment public ou d''infrastructure territoriale ? Si oui, quelles en étaient les particularités par rapport au secteur privé ?", "Quelles difficultés techniques avez-vous rencontrées dans votre parcours et comment les avez-vous surmontées ?", "Pourquoi souhaitez-vous rejoindre une agence publique plutôt que de continuer dans le secteur privé ou libéral ?", "Où vous voyez-vous professionnellement dans 3 à 5 ans, et en quoi ce poste s''inscrit-il dans cette trajectoire ?", "Que savez-vous du rôle et des missions de l''ADER Fès-Meknès, et quels projets de développement territorial de la région connaissez-vous ?", "Selon vous, quelles sont les contraintes spécifiques d''un projet architectural mené dans le cadre d''un marché public au Maroc ?"]','[]','{}','2026-08-27 13:27:12.425201') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions_entretien (id,candidat_id,questions_json,posees_json,coche_par_json,updated_at) VALUES (10,10,'["Pouvez-vous décrire les étapes que vous suivez pour élaborer un dossier de permis de construire, de la conception jusqu''au dépôt ?", "Quels logiciels de conception architecturale maîtrisez-vous, et lequel utilisez-vous le plus couramment dans votre travail quotidien ?", "Comment intégrez-vous les contraintes réglementaires du Plan d''Aménagement Urbain dans vos projets de conception ?", "Quelles missions concrètes avez-vous assurées durant vos deux années d''expérience professionnelle, et dans quel type de structure ?", "Avez-vous déjà travaillé sur un projet d''envergure publique ou d''aménagement urbain ? Si oui, quel était votre rôle précis ?", "Votre Master en Architecture et Urbanisme comprend-il un volet spécifique sur la planification territoriale ou l''habitat, et comment l''avez-vous mis en pratique ?", "Pourquoi postulez-vous à l''ADER plutôt qu''à un cabinet d''architecture privé, alors que votre profil semble plus orienté vers le secteur privé ?", "Où vous voyez-vous professionnellement dans cinq ans, et comment ce poste s''inscrit-il dans cette trajectoire ?", "Que savez-vous des missions principales de l''ADER Fès-Meknès et des projets structurants qu''elle pilote dans la région ?", "Quelle est, selon vous, la différence entre travailler sur un projet architectural dans le secteur public et dans le secteur privé, notamment en termes de contraintes et de délais ?"]','[]','{}','2026-08-27 13:27:26.166508') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions_entretien (id,candidat_id,questions_json,posees_json,coche_par_json,updated_at) VALUES (11,11,'["Quels logiciels de conception architecturale maîtrisez-vous, et pouvez-vous décrire un projet sur lequel vous les avez utilisés concrètement ?", "Comment lisez-vous et interprétez-vous un plan d''exécution architectural, et quels éléments vérifiez-vous en priorité sur un chantier de suivi ?", "Quelle est la différence entre un permis de construire et une autorisation de lotir, et quelles pièces constituent un dossier de demande de permis de construire au Maroc ?", "Votre formation est en Marketing et Commerce International, ce qui est éloigné de l''architecture — qu''est-ce qui vous a conduit vers ce poste et quelles compétences avez-vous développées pour combler cet écart ?", "Durant vos 5 années d''expérience, avez-vous été impliqué dans des projets liés à la construction, à l''urbanisme ou à l''aménagement du territoire, même indirectement ?", "Pouvez-vous citer une situation professionnelle où vous avez dû coordonner plusieurs intervenants sur un projet complexe, et quel a été votre rôle précis ?", "Pourquoi postulez-vous à un poste d''Assistant Architecte alors que votre parcours académique et professionnel ne s''y rattache pas directement, et quel plan avez-vous pour acquérir les compétences manquantes ?", "Où vous voyez-vous professionnellement dans 3 à 5 ans, et en quoi ce poste à l''ADER s''inscrit-il dans cette trajectoire ?", "Que savez-vous des missions de l''Agence de Développement Régional de Fès-Meknès, et quels projets structurants menés par l''ADER avez-vous identifiés avant cet entretien ?", "Le secteur public impose des contraintes spécifiques — délais réglementaires, marchés publics, reddition de comptes — comment vous y préparez-vous et en quoi cela diffère-t-il de votre expérience actuelle ?"]','[]','{}','2026-08-27 13:27:41.062883') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions_entretien (id,candidat_id,questions_json,posees_json,coche_par_json,updated_at) VALUES (12,12,'["Pouvez-vous nous expliquer ce que vous comprenez du rôle d''un assistant architecte au sein d''un organisme de développement régional ?", "Avez-vous des notions de base en lecture de plans architecturaux ou en logiciels comme AutoCAD ou SketchUp, même dans un cadre scolaire ou personnel ?", "Quelle est, selon vous, la différence entre un permis de construire et une autorisation de lotir, et à quoi servent-ils ?", "Votre diplôme est en Informatique et Intelligence Artificielle — qu''est-ce qui vous a amené à postuler pour un poste d''Assistant Architecte ?", "Durant votre formation au lycée Al Khawarizmi, avez-vous réalisé des projets ou travaux en lien avec la conception, la modélisation ou l''urbanisme ?", "En dehors de votre cursus scolaire, avez-vous entrepris des formations complémentaires, des stages ou des auto-apprentissages en rapport avec l''architecture ou le bâtiment ?", "Pourquoi souhaitez-vous intégrer le secteur de l''architecture et de l''aménagement du territoire plutôt que de poursuivre dans votre domaine de formation initial ?", "Où vous voyez-vous professionnellement dans 3 à 5 ans, et comment ce poste s''inscrit-il dans ce parcours ?", "Que savez-vous des missions principales de l''Agence de Développement Régional Fès-Meknès et des projets qu''elle pilote dans la région ?", "Selon vous, quelles sont les contraintes spécifiques du travail dans un établissement public par rapport au secteur privé ?"]','[]','{}','2026-08-27 13:27:53.307849') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions_entretien (id,candidat_id,questions_json,posees_json,coche_par_json,updated_at) VALUES (13,13,'["Quels sont les principes fondamentaux d''un projet architectural et quelle est la différence entre un permis de construire et un permis d''aménager ?", "Comment lisez-vous un plan architectural et quels logiciels de conception (AutoCAD, Revit, SketchUp) maîtrisez-vous concrètement ?", "Qu''est-ce qu''un cahier des charges techniques dans un projet de construction et quel rôle joue l''assistant architecte dans sa rédaction ?", "Votre diplôme est en Marketing et Communication : qu''est-ce qui vous a conduit à postuler à un poste d''Assistant Architecte et qu''avez-vous fait concrètement pour combler cet écart de formation ?", "Décrivez précisément l''expérience professionnelle d''une année que vous avez acquise : en quoi était-elle liée, même partiellement, à l''architecture ou à l''aménagement ?", "Avez-vous suivi des formations complémentaires, des stages ou des projets personnels en lien avec l''architecture ou l''urbanisme depuis l''obtention de votre diplôme ?", "Pourquoi souhaitez-vous travailler dans le secteur public plutôt que dans une agence privée de communication ou d''événementiel, domaine de votre formation initiale ?", "Où vous voyez-vous professionnellement dans 3 ans, et comment ce poste d''Assistant Architecte s''inscrit-il dans ce projet ?", "Que savez-vous du rôle et des missions de l''Agence de Développement Régional Fès-Meknès, et citez un projet territorial qu''elle a porté ou qu''elle accompagne ?", "Selon vous, quels sont les principaux défis du développement urbain et architectural dans la région Fès-Meknès aujourd''hui ?"]','[]','{}','2026-08-27 13:28:05.469229') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions_entretien (id,candidat_id,questions_json,posees_json,coche_par_json,updated_at) VALUES (14,14,'["Quelles méthodes utilisez-vous pour planifier et suivre l''avancement d''un chantier de génie civil en phase d''exécution, et quels outils de gestion de projet maîtrisez-vous ?", "Comment gérez-vous un écart significatif entre le budget prévisionnel et le coût réel d''un projet en cours de réalisation ?", "Face à un désaccord technique avec un bureau d''études ou un entrepreneur sur le respect des normes de construction, quelle démarche adoptez-vous pour trancher et assurer la conformité des travaux ?", "Pouvez-vous décrire le projet le plus complexe que vous avez supervisé depuis votre sortie de l''EHTP en 2020, et quel était votre rôle précis dans sa conduite ?", "Au cours de vos 6 années d''expérience, avez-vous travaillé sur des projets d''infrastructure publique ou d''aménagement urbain, et quelles contraintes spécifiques avez-vous rencontrées ?", "Qu''est-ce qui a le plus évolué dans votre manière de gérer des projets entre votre première année professionnelle et aujourd''hui ?", "Pourquoi souhaitez-vous rejoindre l''ADER Fès-Meknès à ce stade de votre carrière, et qu''espérez-vous apporter concrètement à l''agence ?", "Où vous projetez-vous professionnellement dans 5 ans, et en quoi ce poste de CGM s''inscrit-il dans cette trajectoire ?", "Que savez-vous des missions et des projets portés par l''ADER Fès-Meknès, et quel est selon vous le défi territorial le plus urgent auquel la région doit répondre ?", "Le secteur public impose des contraintes réglementaires et des délais de décision souvent différents du privé — comment vous adapteriez-vous à ce cadre, et l''avez-vous déjà expérimenté ?"]','[]','{}','2026-08-27 13:28:18.000225') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions_entretien (id,candidat_id,questions_json,posees_json,coche_par_json,updated_at) VALUES (15,15,'["Quels logiciels de dessin technique maîtrisez-vous (AutoCAD, Revit, ArchiCAD…) et à quel niveau d''utilisation concrète ?", "Comment établissez-vous un plan d''exécution à partir d''un avant-projet sommaire, et quelles vérifications effectuez-vous avant validation ?", "Quelle est la différence entre un plan de coffrage et un plan d''armature, et avez-vous déjà produit ce type de documents ?", "Décrivez précisément votre expérience d''un an : quel type de projets, quelles tâches quotidiennes et quel était votre niveau de responsabilité ?", "Avez-vous déjà travaillé en coordination avec des équipes chantier ou des bureaux d''études, et comment gériez-vous les écarts entre les plans et la réalité terrain ?", "Votre formation à l''ISTA de Fès couvre principalement le dessin de bâtiment : quelles compétences avez-vous développées par vous-même au-delà du programme officiel ?", "Le score de correspondance entre votre profil et le poste CGM est faible — qu''est-ce qui vous a tout de même poussé à candidater et comment comptez-vous combler les écarts identifiés ?", "Où vous voyez-vous professionnellement dans trois ans, et en quoi ce poste à l''ADER s''inscrit-il dans cette trajectoire ?", "Que savez-vous des missions et des projets portés par l''Agence de Développement Régional Fès-Meknès, et qu''est-ce qui vous a marqué dans son action territoriale ?", "Le secteur public impose des procédures strictes (marchés publics, délais administratifs, reddition de comptes) — comment envisagez-vous de vous adapter à ce cadre après une expérience en secteur privé ?"]','[]','{}','2026-08-27 13:28:31.273254') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions_entretien (id,candidat_id,questions_json,posees_json,coche_par_json,updated_at) VALUES (16,16,'["Comment élaborez-vous un cahier des charges de gestion de projet urbain, et quels indicateurs de performance utilisez-vous pour en assurer le suivi ?", "Dans le cadre d''un projet d''aménagement territorial, comment coordonnez-vous les interventions entre les différents acteurs techniques, administratifs et financiers ?", "Quelle méthodologie appliquez-vous pour identifier et gérer les risques d''un projet d''infrastructure urbaine à différentes phases de son exécution ?", "Parlez-nous d''un projet concret que vous avez piloté ou auquel vous avez contribué significativement durant vos 4 années d''expérience, et quel a été votre rôle précis ?", "En quoi votre formation en architecture et urbanisme à l''ESA de Fès vous apporte-t-elle une valeur ajoutée pour un poste orienté gestion et coordination de projets ?", "Avez-vous déjà travaillé dans un environnement multi-parties prenantes incluant des collectivités territoriales ou des institutions publiques ? Comment avez-vous géré les contraintes réglementaires rencontrées ?", "Pourquoi souhaitez-vous rejoindre l''ADER Fès-Meknès à ce stade de votre parcours professionnel ?", "Où vous projetez-vous dans 5 ans, et en quoi ce poste de CGM s''inscrit-il dans votre trajectoire professionnelle ?", "Que savez-vous des missions et des projets structurants portés par l''ADER Fès-Meknès dans la région ?", "Quelle est votre lecture des enjeux actuels du développement régional au Maroc, notamment dans le contexte de la régionalisation avancée ?"]','[]','{}','2026-08-27 13:28:42.247262') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions_entretien (id,candidat_id,questions_json,posees_json,coche_par_json,updated_at) VALUES (17,17,'["Quelles méthodes utilisez-vous concrètement pour analyser la compétitivité d''un territoire et identifier ses avantages comparatifs pour attirer des investisseurs ?", "Comment construisez-vous une stratégie de prospection commerciale ciblée, et quels outils de suivi mettez-vous en place pour mesurer les résultats ?", "Face à un investisseur étranger hésitant entre deux régions, quels arguments commerciaux et territoriaux mobilisez-vous pour conclure en faveur de Fès-Meknès ?", "En 5 ans d''expérience, quel est le dossier commercial le plus complexe que vous avez géré, et comment l''avez-vous mené à terme ?", "Votre licence en Marketing et Commerce International date de 2020 : quelles compétences avez-vous développées sur le terrain qui complètent ou dépassent cette formation initiale ?", "Avez-vous déjà travaillé sur des projets impliquant des partenaires institutionnels ou publics, et comment avez-vous géré les contraintes liées à ce type d''environnement ?", "Pourquoi postulez-vous à l''ADER Fès-Meknès plutôt que dans une entreprise privée, alors que votre profil est orienté commerce et marketing ?", "Où vous voyez-vous dans 3 ans au sein d''une structure comme l''ADER, et quel impact concret souhaitez-vous avoir sur le développement régional ?", "Que savez-vous du rôle et des missions de l''ADER Fès-Meknès, et citez un projet ou une initiative récente de l''agence que vous avez retenu ?", "Selon vous, quelles sont les deux principales contraintes qui freinent l''attractivité économique de la région Fès-Meknès, et que proposeriez-vous pour y remédier ?"]','[]','{}','2026-08-27 13:28:53.894566') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions_entretien (id,candidat_id,questions_json,posees_json,coche_par_json,updated_at) VALUES (18,18,'["Quels outils utilisez-vous concrètement pour suivre et contrôler la gestion d''un projet ou d''un budget, même à petite échelle ?", "Comment définissez-vous un indicateur de performance pertinent pour mesurer l''avancement d''un projet dans une organisation publique ?", "Si vous deviez identifier un écart entre les objectifs fixés et les résultats obtenus, quelle démarche adopteriez-vous pour analyser et corriger la situation ?", "Votre formation est en Informatique et Intelligence Artificielle — qu''est-ce qui vous a amené à vous orienter vers un poste de contrôle et gestion plutôt que vers un métier purement technique ?", "Durant votre année d''expérience, avez-vous eu à produire des rapports, des tableaux de bord ou des synthèses destinés à des responsables ? Décrivez une situation précise.", "Quelle est la compétence principale que vous avez développée depuis votre baccalauréat en 2023, et en quoi est-elle utile pour ce poste ?", "Pourquoi souhaitez-vous intégrer l''ADER Fès-Meknès aujourd''hui, et qu''est-ce que ce poste représente pour vous dans votre parcours professionnel ?", "Où vous voyez-vous dans trois ans, et comment ce poste de CGM s''inscrit-il dans votre projet professionnel à long terme ?", "Que savez-vous des missions principales de l''ADER Fès-Meknès et du rôle qu''elle joue dans le développement de la région ?", "Selon vous, quelles sont les contraintes spécifiques du travail dans un établissement public par rapport au secteur privé, et êtes-vous prêt à y faire face ?"]','[]','{}','2026-08-27 13:29:22.334015') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions_entretien (id,candidat_id,questions_json,posees_json,coche_par_json,updated_at) VALUES (19,19,'["Comment définissez-vous un plan de communication adapté à une institution publique régionale, et quels outils utiliseriez-vous pour mesurer son impact ?", "Quelles étapes suivez-vous pour concevoir et piloter un événement institutionnel de bout en bout, du brief client à l''évaluation post-événement ?", "Comment assurez-vous la cohérence d''une identité de marque territoriale à travers différents supports de communication (print, digital, événementiel) ?", "Parlez-moi d''un projet concret que vous avez géré seul durant vos 3 années d''expérience, en précisant votre rôle exact et les résultats obtenus.", "Avez-vous déjà travaillé avec des parties prenantes multiples (élus, partenaires institutionnels, prestataires) ? Comment avez-vous géré les désaccords ou les priorités contradictoires ?", "Votre formation est orientée marketing et événementiel privé — comment avez-vous développé des compétences applicables à un contexte institutionnel ou public ?", "Pourquoi postulez-vous à l''ADER Fès-Meknès plutôt qu''à une agence de communication ou une entreprise privée ?", "Où vous voyez-vous professionnellement dans 3 ans, et en quoi ce poste s''inscrit-il dans cette trajectoire ?", "Que savez-vous des missions principales de l''ADER Fès-Meknès et de son rôle dans le développement économique de la région ?", "Quelle est, selon vous, la différence fondamentale entre la communication d''une institution publique comme l''ADER et celle d''une entreprise commerciale ?"]','[]','{}','2026-08-27 13:29:32.795784') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions_entretien (id,candidat_id,questions_json,posees_json,coche_par_json,updated_at) VALUES (20,20,'["Quelles méthodes utilisez-vous concrètement pour contrôler la qualité d''exécution sur un chantier de bâtiment en phase gros œuvre ?", "Comment procédez-vous pour détecter et gérer un écart entre les plans d''exécution et les travaux réalisés sur le terrain ?", "Quels outils ou logiciels avez-vous utilisés pour le suivi technique et administratif d''un chantier, et comment en avez-vous exploité les données ?", "Décrivez un projet sur lequel vous avez travaillé ces 4 dernières années où vous étiez directement responsable du contrôle ou du suivi des travaux.", "Avez-vous déjà géré une situation de retard de chantier ou de non-conformité avec un prestataire ? Comment l''avez-vous résolue ?", "Votre formation est en architecture et bâtiment, mais le poste de CGM exige des compétences en gestion de marché public — comment avez-vous comblé cet écart dans votre parcours ?", "Qu''est-ce qui vous a motivé à postuler à l''ADER plutôt qu''à un bureau d''études ou à un cabinet privé d''architecture ?", "Où vous voyez-vous dans 3 ans au sein d''une structure publique comme l''ADER, et quel rôle souhaitez-vous jouer dans le développement régional ?", "Que savez-vous des missions principales de l''ADER Fès-Meknès et des types de projets qu''elle pilote dans la région ?", "Quelle est, selon vous, la différence fondamentale entre travailler sur un chantier privé et gérer un marché public en termes de contraintes et de responsabilités ?"]','[0, 1, 3, 2, 5, 6, 7, 8, 9, 4]','{"0": "Bouchra OUCHENE", "1": "Fati RBIKI", "3": "Fati RBIKI", "2": "Fati RBIKI", "5": "Fati RBIKI", "6": "Fati RBIKI", "7": "Fati RBIKI", "8": "Fati RBIKI", "9": "Fati RBIKI", "4": "Fati RBIKI"}','2026-08-27 13:58:27.791081') ON CONFLICT (id) DO NOTHING;